/// Canonical blockstate key builder shared by the loader and the table check.
///
/// Anvil palettes store `"minecraft:stone[axis=x]"` strings with properties
/// in no guaranteed order; the wire protocol wants a global numeric ID.
/// `canonical_key` sorts `props` by name so every spelling maps to the one
/// table key. Cold path only; the hot path stores mapped IDs.
pub fn canonical_key(name: &str, props: &[(String, String)]) -> String {
    if props.is_empty() {
        return name.to_owned();
    }
    let mut sorted: Vec<(&str, &str)> =
        props.iter().map(|(k, v)| (k.as_str(), v.as_str())).collect();
    sorted.sort_unstable();
    let mut out = String::with_capacity(name.len() + sorted.len() * 8 + 2);
    out.push_str(name);
    out.push('[');
    for (i, (k, v)) in sorted.iter().enumerate() {
        if i > 0 {
            out.push(',');
        }
        out.push_str(k);
        out.push('=');
        out.push_str(v);
    }
    out.push(']');
    out
}

/// Global blockstate ID for a canonical key, or `None` if unknown.
pub fn block_state_id(key: &str) -> Option<u32> {
    BLOCK_STATES
        .binary_search_by(|(k, _)| k.as_bytes().cmp(key.as_bytes()))
        .ok()
        .map(|i| BLOCK_STATES[i].1)
}

